#!/usr/bin/env bash
# Every function's description and grants, in one place. Regenerates
# functions/<name>/<name>.json; never edit those by hand (bin/fnjson.py, as Tasks').
#   table   read        table:rw  + write rows        table:rwd  + delete rows
#   function:<name>     run it        workflow:<name>     start and read its runs
#   connector:<id>      use it        /folder:verbs       a folder
# No function can be granted schedule.create or agent.update on the Lemma, so
# the schedules and the channel connection are made by the app as the person
# (README, "Connecting a channel").
set -euo pipefail
cd "$(dirname "$0")/.."
f() { uv run --no-project python bin/fnjson.py "$@"; }
f incidents_setup_save "Incidents' set-up, once for the Lemma (safe to run again): the Slack connector, #incidents (found, or made), the channel prefix, the repositories to watch [{repo, service, deploy_workflow}], who gets updates by email, the severity words (default SEV1-3), and the schedules the app made. Writes the memory block." incidents_settings:rw connector:slack function:incidents_memory
f incidents_declare "Declare an incident: title (required), severity, service, impact, lead (default the caller), responders. Makes INC-n, opens #inc-n-<slug>, invites the people, pins a header the Lemma keeps current, tells #incidents, asks for a likely cause, and gives the lead their item in Today. From Triage: source triage, source_id, source_url, evidence." incidents_settings incidents_incident:rw incidents_event:rw connector:slack function:incidents_investigate function:incidents_needs_you
f incidents_on_message "A message in an incident's channel (the incident's Slack schedule): kept as an event; Now is redrawn on a mention or when over 5 minutes old." incidents_settings incidents_incident:rw incidents_event:rw function:incidents_refresh
f incidents_on_github "A change in a watched repository (GitHub's push, merged pull_request, deploy workflow_run, release): kept in the change ledger, and as an event on each open incident in that service." incidents_settings incidents_incident incidents_change:rw incidents_event:rw
f incidents_gather "Read an incident (or every open one) in full: the channel since the last read, its threads and pins, and the changes from an hour before it started. Never duplicates. Redraws Now when something came in. For 'catch me up'." incidents_settings incidents_incident:rw incidents_event:rw incidents_change connector:slack function:incidents_refresh
f incidents_refresh "Keep an incident's pinned header and channel topic current, and ask incidents_scribe to redraw its Now from the events only (it lands a minute later, through incidents_scribe_save). header_only skips the redraw." incidents_settings incidents_incident:rw incidents_event connector:slack workflow:incidents-scribe
f incidents_scribe_save "Keep what incidents_scribe wrote: an incident's Now line (then the header is redrawn), or a drafted status update that waits for the lead." incidents_settings incidents_incident:rw incidents_update:rw connector:slack function:incidents_needs_you
f incidents_investigate "Ask incidents_investigator for a likely cause of an incident (question: what the person asked). It reads the events, the changes before it, and the connectors this Lemma has; it names every source it lacks as not checked and never acts." incidents_settings incidents_incident incidents_event incidents_change incidents_hypothesis workflow:incidents-investigate
f incidents_investigate_save "Keep what incidents_investigator found: a likely cause with its evidence, what it ruled out and what it couldn't check, and post it to the incident's channel." incidents_settings incidents_incident incidents_event:rw incidents_hypothesis:rw connector:slack
f incidents_set "Change an incident's status (declared, investigating, fixing, monitoring), severity, lead (lead_me for 'I'm lead'), comms, responders, impact; mark its write-up reviewed; confirm a likely cause or say it is not it. Writes an event and keeps the header current. Resolve with incidents_resolve." incidents_settings incidents_incident:rw incidents_event:rw incidents_hypothesis:rw connector:slack function:incidents_needs_you
f incidents_draft_update "Ask incidents_scribe to draft an incident's next status update from its events (note: what the lead wants said); the draft lands a minute later. Nothing is sent: the lead sends it with incidents_send_update, after request_approval in Slack." incidents_settings incidents_incident incidents_event incidents_update workflow:incidents-scribe
f incidents_send_update "Send an incident's drafted update (body: the lead's edit) to its channel, #incidents, and by email when this Lemma has a mailbox. Only on the lead's say-so: in Slack, after request_approval. Never sends twice." incidents_settings incidents_incident:rw incidents_event:rw incidents_update:rw connector:slack connector:resend function:incidents_needs_you
f incidents_resolve "Resolve an incident (note: how it was fixed): a last gather, the channel and #incidents told, and the write-up drafted from the events by incidents_writer; the lead then reviews it." incidents_settings incidents_incident:rw incidents_event:rw incidents_hypothesis incidents_update task connector:slack function:incidents_gather function:incidents_needs_you workflow:incidents-writeup
f incidents_writeup_save "Keep incidents_writer's draft: drop citations of anything but the incident's events, flag claims nothing backs, propose follow-ups, write /incidents/INC-n.md, and give the lead 'Review the write-up'." incidents_settings incidents_incident:rw incidents_event:rw incidents_flag:rw /incidents:read,write function:incidents_needs_you
f incidents_followup "Make an incident's follow-up a team task (source incidents), accept or set aside a proposed one (proposal, dismiss), or hand the revert to an agent (revert, change: '#2291'): the Lemma's assistant until Coding agent ships." incidents_incident:rw incidents_event:rw incidents_hypothesis task:rw
f incidents_tick "Every 15 minutes: gather every open incident, draft the update when one is due, and write this person's items in Today. Nothing to do with no open incident." incidents_settings incidents_incident incidents_update function:incidents_gather function:incidents_draft_update function:incidents_needs_you
f incidents_needs_you "What in Incidents needs the person, written to the shared needs_you list (Today reads it): do (an incident they lead), decide (send a due update, review a write-up). Runs as the person; resolves what no longer applies." incidents_settings incidents_incident incidents_update incidents_flag needs_you:rw
f incidents_memory "Tells this Lemma's agents that Incidents is installed: its own block in /memory/AGENTS.md and its guide at /memory/plugins/incidents.md, leaving the team's notes alone. Set-up runs it; safe to run again. remove takes both out." /memory:read,write
f incidents_sample_data "load: made-up incidents to look around (INC-14 open on checkout-api; INC-11 to INC-13 resolved, with write-ups and follow-ups). clear: removes only what the sample made." incidents_settings:rw incidents_incident:rwd incidents_event:rwd incidents_change:rwd incidents_hypothesis:rwd incidents_update:rwd incidents_flag:rwd incidents_sample_row:rwd task:rwd function:incidents_needs_you
